Given an array arr[], the task is to print the subarray having maximum sum.Examples:Input: arr[] = {2, 3, -8, 7, -1, 2, 3}Output: {7, -1, 2, 3}Explanation: The subarray {7, -1, 2, 3} has the largest sum 11.Input: arr[] = {-2, -5, 6, -2, -3, 1, 5, -6}Output: {6, -2, -3, 1, 5}Explanation: The subarray {6, -2, -3, 1, 5} has the largest sum of 7.Try It YourselfTable of Content[Naive Approach] By iterating over all subarrays - O(n^2) Time and O(1) Space[Expected Approach] Using Kadane's Algorithm - O(n) Time and O(1) Space[Naive Approach] By iterating over all subarrays - O(n^2) Time and O(1) SpaceThe idea is to run two nested loops to iterate over all possible subarrays and find the maximum sum. The outer loop will mark the starting point of a subarray and inner loop will mark the ending point of the subarray. At any time, if we find a subarray whose sum is greater than the maximum sum so far, then we will update the starting and ending point of the maximum sum subarray.
            C++

    // C++ Program to print subarray with maximum sum using nested loops 

#include <bits/stdc++.h>
using namespace std;

// Function to find the subarray with maximum sum
vector<int> maxSumSubarray(vector<int> &arr) {

    // start and end of max sum subarray
    int resStart = 0, resEnd = 0;

    // Initialize the maximum subarray sum with the first element
    int maxSum = arr[0];

    for (int i = 0; i < arr.size(); i++) {

        // Initialize current subarray sum with 0
        int currSum = 0;
        for(int j = i; j < arr.size(); j++) {
            currSum += arr[j];

            // If current subarray has greater sum than maximum sum subarray,
            // then update the start and end of maximum sum subarray
            if(currSum > maxSum) {
                maxSum = currSum;
                resStart = i;
              	resEnd = j;
            }
        }
    }

    vector<int> res;
    for(int i = resStart; i <= resEnd; i++)
        res.push_back(arr[i]);
    return res;
}

int main() {
    vector<int> arr = {2, 3, -8, 7, -1, 2, 3};
    vector<int> res = maxSumSubarray(arr);

    for(int i = 0; i < res.size(); i++)
        cout << res[i] << " ";

    return 0;
}


